package com.mygo.music;

import android.app.*;
import android.content.*;
import android.graphics.*;
import android.net.Uri;
import android.widget.*;
import org.json.*;
import java.io.*;
import java.net.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.zip.*;
import com.google.zxing.*;
import com.google.zxing.common.*;

/** Original provider scripts against controlled protocol servers, with actual Android UI and I/O. */
final class ProviderFlowChecks {
    private final Instrumentation test;private final Context context;
    ProviderFlowChecks(Instrumentation test){this.test=test;context=test.getTargetContext();}
    static void check(boolean value,String message){if(!value)throw new AssertionError(message);}
    private String asset(String file)throws Exception{try(InputStream in=test.getContext().getAssets().open(file)){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return out.toString("UTF-8");}}
    private String call(PluginRuntime runtime,String method,JSONObject args)throws Exception{CountDownLatch done=new CountDownLatch(1);boolean[] ok={false};String[] result={""};runtime.call(method,args,(success,raw)->{ok[0]=success;result[0]=raw;done.countDown();});check(done.await(25,TimeUnit.SECONDS),"provider callback missing: "+method);check(ok[0],method+": "+result[0]);return result[0];}
    private String call(PluginManager manager,String id,String method,JSONObject args)throws Exception{CountDownLatch done=new CountDownLatch(1);boolean[] ok={false};String[] result={""};manager.export(id,method,args,(success,raw)->{ok[0]=success;result[0]=raw;done.countDown();});check(done.await(25,TimeUnit.SECONDS),"manager callback missing: "+method);check(ok[0],method+": "+result[0]);return result[0];}
    private void install(PluginManager manager,String id,String mode,String source)throws Exception{ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(ZipOutputStream zip=new ZipOutputStream(bytes)){zip.putNextEntry(new ZipEntry("plugin.json"));zip.write(new JSONObject().put("id",id).put("main","index.js").put("playback",mode).put("permissions",new JSONObject().put("network",new JSONArray().put("127.0.0.1"))).toString().getBytes("UTF-8"));zip.closeEntry();zip.putNextEntry(new ZipEntry("index.js"));zip.write(source.getBytes("UTF-8"));zip.closeEntry();}CountDownLatch done=new CountDownLatch(1);String[] result={""};boolean[] ok={false};manager.installZipStream(new ByteArrayInputStream(bytes.toByteArray()),(success,raw)->{ok[0]=success;result[0]=raw;done.countDown();});check(done.await(30,TimeUnit.SECONDS)&&ok[0],"provider install: "+result[0]);}
    private void remove(String id){PluginArchive.delete(new File(context.getFilesDir(),"plugins/"+id));}
    void run()throws Exception{testQrAndSettings();testKugouAccount();testSpotifyRemote();}
    private void testQrAndSettings()throws Exception{
        String payload="https://example.com/scan?token=fixture";Bitmap bitmap=PluginQrImage.create(payload);int[] pixels=new int[bitmap.getWidth()*bitmap.getHeight()];bitmap.getPixels(pixels,0,bitmap.getWidth(),0,0,bitmap.getWidth(),bitmap.getHeight());Result decoded=new MultiFormatReader().decode(new BinaryBitmap(new HybridBinarizer(new RGBLuminanceSource(bitmap.getWidth(),bitmap.getHeight(),pixels))));check(payload.equals(decoded.getText()),"saved login QR cannot be scanned");
        Uri image=PluginQrImage.save(context,bitmap);try(InputStream in=context.getContentResolver().openInputStream(image)){Bitmap restored=BitmapFactory.decodeStream(in);check(restored!=null&&restored.getWidth()==640,"QR PNG not readable from MediaStore");}finally{context.getContentResolver().delete(image,null,null);}
        JSONObject specification=new JSONObject("{\"options\":[{\"value\":\"qq\",\"label\":\"QQ\"},{\"value\":\"wechat\",\"label\":\"微信\"}]}");test.runOnMainSync(()->{PluginSettingField field=new PluginSettingField(context,specification,"wechat");check(field.view instanceof Spinner&&field.value().equals("wechat"),"login method setting lost selected value");((Spinner)field.view).setSelection(1);check(field.value().equals("qq"),"login method selector does not save the protocol value");PluginSettingField unknown=new PluginSettingField(context,specification,"custom");check(unknown.value().equals("custom"),"unknown setting overwritten");});
    }
    private void testKugouAccount()throws Exception{
        try(ProtocolServer server=new ProtocolServer(false)){String id="kugou-auth-protocol";File directory=new File(context.getCacheDir(),id);directory.mkdirs();String bridge="const originalFetch=globalThis.fetch;globalThis.fetch=(url,options)=>{const u=new URL(url);return originalFetch('"+server.base()+"'+u.pathname+u.search,options);};\n";
            try(FileOutputStream out=new FileOutputStream(new File(directory,"index.js"))){out.write((bridge+asset("kugou-original.js")).getBytes("UTF-8"));}try(FileOutputStream out=new FileOutputStream(new File(directory,"plugin.json"))){out.write(new JSONObject().put("id",id).put("main","index.js").put("permissions",new JSONObject().put("network",new JSONArray().put("127.0.0.1"))).toString().getBytes("UTF-8"));}
            context.getSharedPreferences("library",0).edit().putBoolean("plugin_network_"+id,true).commit();context.getSharedPreferences("plugin_settings_"+id,0).edit().putString("autoVip","0").commit();context.getSharedPreferences("plugin_data_"+id,0).edit().clear().putString("dfid","\"fixture-device\"").commit();
            Activity activity=test.startActivitySync(new Intent(context,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));PluginRuntime runtime=new PluginRuntime(activity,directory);PluginRuntime restored=null;try{check("null".equals(call(runtime,"account",new JSONObject())),"Kugou starts signed in");JSONObject account=new JSONObject(call(runtime,"signIn",new JSONObject()));check(account.getString("id").equals("2468"),"original Kugou QR sign-in failed");java.lang.reflect.Field dialog=PluginRuntime.class.getDeclaredField("loginDialog");dialog.setAccessible(true);test.runOnMainSync(()->{try{AlertDialog prompt=(AlertDialog)dialog.get(runtime);check(prompt!=null&&!prompt.isShowing(),"successful provider login left its QR window open");}catch(Exception error){throw new RuntimeException(error);}});runtime.dispose();restored=new PluginRuntime(activity,directory);check(new JSONObject(call(restored,"account",new JSONObject())).getString("id").equals("2468"),"Kugou login not persisted across runtime restart");String track="0123456789ABCDEF0123456789ABCDEF";JSONObject stream=new JSONObject(call(restored,"stream",new JSONObject().put("id",track).put("quality","lossless")));check(stream.getString("url").equals(server.base()+"/audio.mp3")&&server.authenticatedStream,"Kugou stream resolution did not send its stored account");call(restored,"signOut",new JSONObject());check("null".equals(call(restored,"account",new JSONObject())),"Kugou sign-out did not remove account");}finally{runtime.dispose();if(restored!=null)restored.dispose();test.runOnMainSync(activity::finish);}
        }
    }
    private void testSpotifyRemote()throws Exception{
        String id="spotify-remote-protocol";PluginManager manager=new PluginManager(context);PluginRemote[] controller={null};try(ProtocolServer server=new ProtocolServer(true)){
            String source=asset("spotify-original.js").replace("https://api.spotify.com/v1",server.base()+"/v1");install(manager,id,"remote",source);context.getSharedPreferences("library",0).edit().putBoolean("plugin_network_"+id,true).commit();context.getSharedPreferences("plugin_data_"+id,0).edit().clear().putString("session",new JSONObject().put("access","fixture-access").put("refresh","fixture-refresh").put("expiresAt",System.currentTimeMillis()+3600000).toString()).putString("me","\"fixture-owner\"").putString("queue","{\"owner\":\"fixture-owner\",\"id\":\"queue-id\"}").commit();CountDownLatch played=new CountDownLatch(1),state=new CountDownLatch(1);String[] failure={""};
            test.runOnMainSync(()->{controller[0]=new PluginRemote(manager,new PluginRemote.Listener(){public void state(JSONObject value){state.countDown();}public void error(String message){failure[0]=message;}});controller[0].play(id,new JSONArray().put("track-a").put("track-b"),1,300,(ok,raw)->{if(!ok)failure[0]=raw;played.countDown();});});check(played.await(15,TimeUnit.SECONDS)&&state.await(10,TimeUnit.SECONDS)&&failure[0].isEmpty(),"original Spotify remote playback: "+failure[0]);check(server.authenticatedStream&&server.queue.equals("spotify:track:track-b"),"remote queue, device or bearer token lost");
            test.runOnMainSync(()->{check(controller[0].active()&&controller[0].position()==300&&controller[0].duration()==60000,"remote state did not update controller");controller[0].toggle();});server.await("pause");check(!new JSONObject(call(manager,id,"remoteState",new JSONObject())).getBoolean("playing"),"remote pause not sent to provider");awaitPlaying(controller[0],false);test.runOnMainSync(()->controller[0].toggle());server.await("resume");test.runOnMainSync(()->controller[0].seek(4567));server.await("seek");test.runOnMainSync(()->controller[0].volume(37));server.await("volume");JSONArray devices=new JSONArray(call(manager,id,"remoteDevices",new JSONObject()));check(devices.length()==2,"provider devices not available");test.runOnMainSync(()->controller[0].use("device-b"));server.await("use");JSONObject result=new JSONObject(call(manager,id,"remoteState",new JSONObject()));check(result.getInt("position")==4567&&result.getInt("volume")==37&&result.getString("device").equals("Device B"),"remote seek/volume/device state lost");
            test.runOnMainSync(()->controller[0].clear(true));server.await("pause-again");check(!controller[0].active(),"switching away left remote source active");
        }finally{test.runOnMainSync(()->{if(controller[0]!=null)controller[0].close();manager.close();});remove(id);}
    }
    private void awaitPlaying(PluginRemote controller,boolean expected)throws Exception{long deadline=android.os.SystemClock.elapsedRealtime()+7000;boolean[] matches={false};while(!matches[0]&&android.os.SystemClock.elapsedRealtime()<deadline){test.runOnMainSync(()->matches[0]=controller.playing()==expected);android.os.SystemClock.sleep(25);}check(matches[0],"controller playback state was not refreshed");}
    private static final class ProtocolServer implements AutoCloseable {
        final ServerSocket socket=new ServerSocket(0);final Set<String> operations=ConcurrentHashMap.newKeySet();volatile boolean authenticatedStream;volatile String queue="";boolean spotify,playing;int position,volume=80,pauses,stateFailures=2;String device="device-a";
        ProtocolServer(boolean spotify)throws Exception{this.spotify=spotify;Thread worker=new Thread(()->{while(!socket.isClosed())try(Socket connection=socket.accept()){respond(connection);}catch(Exception error){if(!socket.isClosed())operations.add("SERVER_ERROR:"+error);}});worker.setDaemon(true);worker.start();}
        String base(){return "http://127.0.0.1:"+socket.getLocalPort();}
        void await(String operation)throws Exception{long deadline=android.os.SystemClock.elapsedRealtime()+8000;while(!operations.contains(operation)&&android.os.SystemClock.elapsedRealtime()<deadline)android.os.SystemClock.sleep(25);check(operations.contains(operation),"provider operation missing: "+operation+" "+operations);}
        void respond(Socket connection)throws Exception{connection.setSoTimeout(5000);BufferedReader in=new BufferedReader(new InputStreamReader(connection.getInputStream(),"UTF-8"));String request=in.readLine();if(request==null)return;String[] first=request.split(" ");Map<String,String> headers=new HashMap<>();String line;while((line=in.readLine())!=null&&!line.isEmpty()){int colon=line.indexOf(':');if(colon>0)headers.put(line.substring(0,colon).toLowerCase(Locale.ROOT),line.substring(colon+1).trim());}int length=Integer.parseInt(headers.getOrDefault("content-length","0"));char[] body=new char[length];int count=0,n;while(count<length&&(n=in.read(body,count,length-count))>0)count+=n;String raw=new String(body,0,count);URI uri=new URI(first[1]);String path=uri.getPath();Map<String,String> query=new HashMap<>();if(uri.getRawQuery()!=null)for(String pair:uri.getRawQuery().split("&")){String[] item=pair.split("=",2);query.put(URLDecoder.decode(item[0],"UTF-8"),item.length==2?URLDecoder.decode(item[1],"UTF-8"):"");}String response;int httpStatus=200;
            if(!spotify){JSONObject data=new JSONObject();if(path.endsWith("/qrcode"))data.put("qrcode","fixture-code");else if(path.endsWith("/get_userinfo_qrcode"))data.put("status",4).put("token","fixture-token").put("userid",2468).put("nickname","Fixture listener");else if(path.equals("/v5/url")){authenticatedStream="fixture-token".equals(query.get("token"))&&"2468".equals(query.get("userid"))&&query.containsKey("signature");data.put("url",new JSONArray().put(base()+"/audio.mp3")).put("extName","mp3").put("bitRate",320);}else throw new IOException("unexpected Kugou route: "+path);response=new JSONObject().put("status",1).put("error_code",0).put("data",data).toString();}
            else{check("Bearer fixture-access".equals(headers.get("authorization")),"Spotify bearer token missing");response="{}";if(path.equals("/v1/me/player")&&first[0].equals("GET")&&stateFailures-->0){httpStatus=503;response="{\"error\":{\"message\":\"transient fixture failure\"}}";}else if(path.endsWith("/devices"))response="{\"devices\":[{\"id\":\"device-a\",\"name\":\"Device A\",\"is_active\":true},{\"id\":\"device-b\",\"name\":\"Device B\"}]}";else if(path.endsWith("/items")){queue=new JSONObject(raw).getJSONArray("uris").getString(0);}else if(path.endsWith("/play")){playing=true;if(!raw.isEmpty()){JSONObject data=new JSONObject(raw);position=data.optInt("position_ms");authenticatedStream="spotify:playlist:queue-id".equals(data.optString("context_uri"))&&"device-a".equals(query.get("device_id"));}else operations.add("resume");}else if(path.endsWith("/pause")){playing=false;operations.add(++pauses>1?"pause-again":"pause");}else if(path.endsWith("/seek")){position=Integer.parseInt(query.get("position_ms"));operations.add("seek");}else if(path.endsWith("/volume")){volume=Integer.parseInt(query.get("volume_percent"));operations.add("volume");}else if(path.equals("/v1/me/player")&&first[0].equals("PUT")){device=new JSONObject(raw).getJSONArray("device_ids").getString(0);operations.add("use");}else if(path.equals("/v1/me/player")){response=new JSONObject().put("is_playing",playing).put("progress_ms",position).put("item",new JSONObject().put("id","track-b").put("duration_ms",60000)).put("device",new JSONObject().put("name",device.equals("device-b")?"Device B":"Device A").put("volume_percent",volume)).toString();}else throw new IOException("unexpected Spotify route: "+path);}
            byte[] bytes=response.getBytes("UTF-8");connection.getOutputStream().write(("HTTP/1.1 "+httpStatus+" Test\r\nContent-Type: application/json\r\nContent-Length: "+bytes.length+"\r\nConnection: close\r\n\r\n").getBytes("US-ASCII"));connection.getOutputStream().write(bytes);connection.getOutputStream().flush();
        }
        public void close()throws Exception{socket.close();}
    }
}
